-- Adds team_chat:use / manage_channels / moderate to the built-in roles. System roles are immutable, so the guard trigger is dropped for this migration and recreated.
DROP TRIGGER roles_system_no_update;
UPDATE roles SET permissions = '["conversations:read","conversations:reply","conversations:assign","conversations:delete","contacts:read","contacts:write","contacts:import","contacts:delete","inboxes:manage","members:read","members:manage","roles:manage","settings:read","settings:write","channels:manage","tokens:manage","templates:manage","kb:manage","ai:use","billing:manage","payments:request","analytics:read","analytics:export","analytics_identity:manage","api_keys:manage","audit:read","team_chat:use","team_chat:manage_channels","team_chat:moderate"]' WHERE id = 'role_owner';
UPDATE roles SET permissions = '["conversations:read","conversations:reply","conversations:assign","conversations:delete","contacts:read","contacts:write","contacts:import","contacts:delete","inboxes:manage","members:read","members:manage","settings:read","settings:write","channels:manage","tokens:manage","templates:manage","kb:manage","ai:use","payments:request","analytics:read","analytics:export","api_keys:manage","audit:read","team_chat:use","team_chat:manage_channels","team_chat:moderate"]' WHERE id = 'role_manager';
UPDATE roles SET permissions = '["conversations:read","conversations:reply","contacts:read","contacts:write","members:read","settings:read","ai:use","payments:request","team_chat:use"]' WHERE id = 'role_agent';
UPDATE roles SET permissions = '["conversations:read","contacts:read","members:read","settings:read","analytics:read","team_chat:use"]' WHERE id = 'role_viewer';
CREATE TRIGGER roles_system_no_update BEFORE UPDATE ON roles WHEN OLD.is_system = 1 BEGIN SELECT RAISE(ABORT, 'system roles are immutable'); END;
-- custom roles that could read conversations may use team chat (the new permission is opt-out for them, not a silent loss of a feature)
UPDATE roles SET permissions = replace(permissions, '"conversations:read"', '"conversations:read","team_chat:use"') WHERE is_system = 0 AND permissions LIKE '%"conversations:read"%' AND permissions NOT LIKE '%team_chat:use%';
